const r=$input.first().json||{};
const base=$('Select Dispatched GitHub Run').first().json||{};
if(Number(r.id)!==Number(base.phaseRun?.id))throw new Error('GITHUB_PHASE_RUN_ID_MISMATCH');
if(r.status!=='completed') throw new Error('GitHub phase did not complete.');
const common={...base,phaseRun:{...base.phaseRun,status:r.status,conclusion:r.conclusion,completedAt:r.updated_at||null},githubPhase:{phaseName:base.phaseName,workflowFile:base.workflowFile,runId:Number(r.id),runNumber:r.run_number,htmlUrl:r.html_url,status:r.status,conclusion:r.conclusion}};
if(r.conclusion!=='success'){
  if(String(base.phaseName||'').includes('Phase 4A')) return [{json:{...common,phase4aSourceCheck:{status:'BLOCKED',reason:'GITHUB_PHASE_RUN_'+String(r.conclusion||'UNKNOWN').toUpperCase(),checkpoint:'phase4a_run_unsuccessful',retryable:false,runId:Number(r.id),message:'Inspect this run and its adapter diagnostics before retrying; GitHub failure alone does not establish source unavailability.'}}}];
  throw new Error(base.phaseName+' failed. Run '+r.id+' conclusion='+r.conclusion);
}
return [{json:common}];
